('lib/content/pa_scolarite/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00303','3.3.8.1 — L’appréhension de l’auteur présumé',303,'string','et compatible avec la présomption d’innocence.','et compatible avec la présomption d’innocence.','{}'::jsonb,true),
