('lib/content/pa_scolarite/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00306','3.3.8.2 — Le mandat de recherche',306,'_Paragraph','contre laquelle il existe une ou plusieurs raisons plausibles de soupçonner la commission d’un crime ou d’un délit ','contre laquelle il existe une ou plusieurs raisons plausibles de soupçonner la commission d’un crime ou d’un délit ','{}'::jsonb,true),
('lib/content/pa_scolarite/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00307','3.3.8.2 — Le mandat de recherche',307,'string','puni d’au moins trois ans d’emprisonnement (art. 70 C.P.P.).','puni d’au moins trois ans d’emprisonnement (art. 70 C.P.P.).','{}'::jsonb,true),
